52	function NewSecurityToken($TokenId, $TokenName) {
53		$SQL = "SELECT tokenid FROM securitytokens WHERE tokenid='" . $TokenId . "'";
54		$Result = DB_query($SQL);
55		if (DB_num_rows($Result) == 0) {
56			$SQL = "INSERT INTO securitytokens (tokenid,
57												tokenname
58											) VALUES (
59												'" . $TokenId . "',
60												'" . $TokenName . "'
61											)";
62			$Response = executeSQL($SQL, false);
63			if ($Response == 0) {
64				OutputResult(__('The security token') . ' ' . $TokenId . ' ' . __('has been created'), 'success');
65			} else {
66				OutputResult(__('The security token') . ' ' . $TokenId . ' ' . __('could not be created') . '<br />' . $SQL, 'error');
67			}
68		} else {
69			OutputResult(__('The security token') . ' ' . $TokenId . ' ' . __('already exists'), 'info');
70		}
71	}
