/* Over the credit limit: the order is created but held for credit control approval, and is not auto-invoiced */
$RecurrValueResult = DB_query("SELECT COALESCE(SUM(unitprice * quantity * (1 - discountpercent)), 0)
								FROM recurrsalesorderdetails WHERE recurrorderno = '" . $RecurrOrderRow['recurrorderno'] . "'");
$RecurrValueRow = DB_fetch_row($RecurrValueResult);
$CreditCheck = CreditOrderCheck($RecurrOrderRow['debtorno'], $RecurrValueRow[0] + $RecurrOrderRow['freightcost']);
if ($CreditCheck['hold']) {
	DB_query("UPDATE salesorders SET creditholdstate = 1 WHERE orderno = '" . $OrderNo . "'");
	$RecurrOrderRow['autoinvoice'] = 0;
	prnMsg(__('Order') . ' ' . $OrderNo . ' ' . __('takes the customer over their credit limit and is held for credit control approval'), 'warn');
}

